def is_k_lucky(ticket, k):
    # This function checks if a ticket is k-lucky
    from itertools import product

    digits = str(ticket)
    n = len(digits)

    # Generate all possible combinations of operations and brackets
    operations = ['+', '-', '*']
    brackets = [(i, j) for i in range(n) for j in range(i+1, n)]

    for ops in product(operations, repeat=n-1):
        for (i, j) in brackets:
            # Create all possible expressions with operations and brackets
            expr = digits[0]
            for k in range(n-1):
                expr += ops[k] + digits[k+1]
            # Evaluate the expression
            if eval(expr[:i+1] + ')' + expr[i+1:]) == k:
                return True
            if eval('(' + expr[:j+1] + ')' + expr[j+1:]) == k:
                return True
    return False

def main():
